                        <div class="bar-row">
                            <div class="bar-label">World Avg</div>
                            <div class="bar-track"><div class="bar-fill" style="width: 32%;">~4.5 t</div></div>
                        </div>
                        <div class="bar-row">
                            <div class="bar-label">Chad / Niger</div>
