                        <div class="bar-row"><div class="bar-label">China</div><div class="bar-track"><div class="bar-fill" style="width: 64%;">9 t</div></div></div>
                        <div class="bar-row"><div class="bar-label">South Africa</div><div class="bar-track"><div class="bar-fill" style="width: 50%;">7 t</div></div></div>
                        <div class="bar-row"><div class="bar-label">EU-27</div><div class="bar-track"><div class="bar-fill" style="width: 43%;">6 t</div></div></div>
                        <div class="bar-row"><div class="bar-label">UK</div><div class="bar-track"><div class="bar-fill low" style="width: 28%;">4 t</div></div></div>
                        <div class="bar-row"><div class="bar-label">India</div><div class="bar-track"><div class="bar-fill" style="width: 14%;">2 t</div></div></div>
                        <div class="bar-row"><div class="bar-label">Kenya</div><div class="bar-track"><div class="bar-fill low" style="width: 3%;">0.4 t</div></div></div>
