    <!-- Slide 8: Energy Mix Matters -->
    <section class="slide">
        <div class="slide-content">
            <div class="slide-header reveal">
                <div class="slide-number">07</div>
                <h2>Energy Mix Explains Why France and the UK Emit Far Less Per Capita Than Germany or the US</h2>
            </div>
            <div class="split-layout">
                <div class="split-text reveal">
                    <p>Even among wealthy nations with similar prosperity and living standards, per capita emissions can vary significantly based on their power grids.</p>
                    <ul class="bullet-list">
                        <li><strong>Low Emitters (per capita):</strong> France, the UK, and Portugal have successfully minimized per capita emissions (UK: ~4 t).</li>
                        <li><strong>The Nuclear & Renewables Factor:</strong> A much higher share of their electricity is generated from nuclear and renewable sources rather than fossil fuels.</li>
                        <li><strong>Higher Emitters (per capita):</strong> Germany and the US (US: ~14 t) maintain higher per capita emission rates due to heavier reliance on fossil-intensive energy infrastructure.</li>
                    </ul>
                </div>
                <div class="split-media reveal">
                    <div class="chart-placeholder">
                        <div class="chart-placeholder-icon">⚡</div>
                        <h3>Diverging Energy Mix Bar Chart</h3>
                        <p>Comparing the share of Nuclear/Renewables vs. Fossil Fuels in the electricity grids of the US, Germany, UK, and France alongside their per capita emissions.</p>
                    </div>
                </div>
            </div>
        </div>
    </section>

    <!-- Slide 9: Key Takeaways -->
    <section class="slide">
        <div class="slide-content">
            <div class="slide-header reveal">
                <div class="slide-number">08</div>
                <h2>Key Takeaways: Responsibility Is Shared but Unequal</h2>
            </div>
            <div class="reveal">
                <ul class="bullet-list" style="margin-left: 0; gap: clamp(1rem, 2.5vh, 1.5rem); max-width: 1000px;">
                    <li><strong>No peak yet:</strong> Global emissions exceed 35 billion tonnes per year and have not yet peaked, despite slowing growth.</li>
                    <li><strong>Dramatic shift in responsibility:</strong> Europe and the US dominated historically (>90% in 1900) but now account for less than one-third.</li>
                    <li><strong>China's complex role:</strong> China is the largest annual emitter (~31%), but its per capita emissions (~9 t) remain well below the US (~14 t).</li>
                    <li><strong>Massive per capita inequality:</strong> A 150x gap persists between the lowest emitters (Sub-Saharan Africa, ~0.1 t) and the highest large-country emitters.</li>
                    <li><strong>Energy policy matters:</strong> Countries with similar prosperity levels can have very different per capita emissions depending on their energy mix and technology choices.</li>
                </ul>
            </div>
        </div>
    </section>

    <script>
        class SlidePresentation {
            constructor() {
                this.slides = document.querySelectorAll('.slide');
                this.progressBar = document.getElementById('progressBar');
                this.setupIntersectionObserver();
                this.setupKeyboardNav();
                this.updateProgress(0);
            }

            setupIntersectionObserver() {
                const observer = new IntersectionObserver((entries) => {
                    entries.forEach(entry => {
                        if (entry.isIntersecting) {
                            entry.target.classList.add('visible');
                            const index = Array.from(this.slides).indexOf(entry.target);
                            this.updateProgress(index);
                        }
                    });
                }, { threshold: 0.5 });

                this.slides.forEach(slide => observer.observe(slide));
            }

            setupKeyboardNav() {
                document.addEventListener('keydown', (e) => {
                    const currentIndex = this.getCurrentSlideIndex();
                    if (e.key === 'ArrowRight' || e.key === 'Space' || e.key === 'PageDown') {
                        if (currentIndex < this.slides.length - 1) {
                            this.slides[currentIndex + 1].scrollIntoView({ behavior: 'smooth' });
                        }
                    } else if (e.key === 'ArrowLeft' || e.key === 'PageUp') {
                        if (currentIndex > 0) {
                            this.slides[currentIndex - 1].scrollIntoView({ behavior: 'smooth' });
                        }
                    }
                });
            }

            getCurrentSlideIndex() {
                let maxVisible = 0;
                let maxIndex = 0;
                const windowHeight = window.innerHeight;

                this.slides.forEach((slide, index) => {
                    const rect = slide.getBoundingClientRect();
                    const visibleHeight = Math.min(rect.bottom, windowHeight) - Math.max(rect.top, 0);
                    if (visibleHeight > maxVisible) {
                        maxVisible = visibleHeight;
                        maxIndex = index;
                    }
                });
                return maxIndex;
            }

            updateProgress(index) {
                if (!this.progressBar) return;
                const percent = ((index + 1) / this.slides.length) * 100;
                this.progressBar.style.width = `${percent}%`;
            }
        }

        document.addEventListener('DOMContentLoaded', () => {
            new SlidePresentation();
        });
    </script>
